    {
      "id": "L5-reviewer-attribution",
      "severity": "soft",
      "description": "reviewerUserId == tannercarlson@vvsvault.com on every approve creates personal discoverability/deposition exposure. The decision is institutional, not personal.",
      "fix": "Log reviewerUserId for internal accountability BUT also stamp reviewerOrgId and treat org as canonical actor in any external-facing artifact. Add Property.sourceAttribution that exposes ONLY 'public-records-research' to customers/sellers, never the individual reviewer."
